import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  LinErpListFilterBar,
  LinReportPeriodSelectorFields,
  Select,
  computeReportPeriodDates,
  dispatchAppToast,
  nowMonth,
  nowQuarter,
  nowYear,
  yearOptionsFromStartYear,
  type ViewMode,
} from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../../../store/hooks';
import { analyticsService } from '../../../services/analytics/analyticsService';
import { formatNumber, formatVnd } from '../../../utils/formatters';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import reportStyles from '../../../styles/erpReportPage.module.css';
import type { WarehouseDto, StockBalanceRow } from '../../../services/analytics/models';
import { AnalyticsReportShell, ReportTableWrap } from '../../../components/report';

const TEST_ID = 'erp-bao-cao-nxt';
const PAGE_ID = 'baocao-nxt';

const BaoCaoNxtPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const startYear = import.meta.env.VITE_START_YEAR ? Number(import.meta.env.VITE_START_YEAR) : undefined;
  const yearOpts = startYear ? yearOptionsFromStartYear(startYear) : undefined;

  const [viewMode, setViewMode] = useState<ViewMode>('month');
  const [month, setMonth] = useState(nowMonth());
  const [year, setYear] = useState(nowYear());
  const [quarter, setQuarter] = useState(nowQuarter());
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [warehouseId, setWarehouseId] = useState('');
  const [warehouses, setWarehouses] = useState<WarehouseDto[]>([]);
  const [rows, setRows] = useState<StockBalanceRow[]>([]);
  const [loading, setLoading] = useState(false);

  const applyPeriodDates = useCallback((mode: ViewMode, m: string, y: string, q: string) => {
    const dates = computeReportPeriodDates(mode, m, y, q);
    setFromDate(dates.fromDate ?? '');
    setToDate(dates.toDate ?? '');
  }, []);

  useEffect(() => {
    applyPeriodDates('month', nowMonth(), nowYear(), nowQuarter());
  }, [applyPeriodDates]);

  useEffect(() => {
    let cancelled = false;
    const t = setTimeout(() => {
      analyticsService
        .getWarehouses()
        .then(d => {
          if (!cancelled) setWarehouses(d);
        })
        .catch(() => {});
    }, 0);
    return () => {
      cancelled = true;
      clearTimeout(t);
    };
  }, []);

  const handleLoad = useCallback(() => {
    if (!fromDate || !toDate) return;
    setLoading(true);
    analyticsService
      .getStockBalance({
        fromDate,
        toDate,
        warehouseId: warehouseId || undefined,
      })
      .then(setRows)
      .catch(err =>
        dispatchAppToast(dispatch, {
          message: getApiErrorMessage(err, 'Lỗi tải báo cáo NXT'),
          type: 'error',
        }),
      )
      .finally(() => setLoading(false));
  }, [fromDate, toDate, warehouseId, dispatch]);

  const handlePeriodModeChange = (mode: ViewMode) => {
    setViewMode(mode);
    applyPeriodDates(mode, month, year, quarter);
  };

  const handleMonthChange = (m: string) => {
    setMonth(m);
    applyPeriodDates(viewMode, m, year, quarter);
  };

  const handleYearChange = (y: string) => {
    setYear(y);
    applyPeriodDates(viewMode, month, y, quarter);
  };

  const handleQuarterChange = (q: string) => {
    setQuarter(q);
    applyPeriodDates(viewMode, month, year, q);
  };

  const totalClosing = useMemo(
    () => rows.reduce((sum, r) => sum + (r.closingAmount ?? 0), 0),
    [rows],
  );

  const listFilters = useMemo(
    () => (
      <LinErpListFilterBar
        testIdPrefix={TEST_ID}
        fromDate={fromDate}
        toDate={toDate}
        onDateChange={(from, to) => {
          setFromDate(from ?? '');
          setToDate(to ?? '');
          setViewMode('day');
        }}
        dateLabel="Thời gian"
        expandDateRangeAriaLabel="Thêm ngày kết thúc"
        onSearch={handleLoad}
        searchAriaLabel="Xem"
        loading={loading}
        dateLeading={(
          <LinReportPeriodSelectorFields
            testIdPrefix={TEST_ID}
            labels={{
              viewMode: 'Xem theo',
              fieldMonth: 'Tháng',
              fieldYear: 'Năm',
              fieldQuarter: 'Quý',
            }}
            viewMode={viewMode}
            month={month}
            year={year}
            quarter={quarter}
            yearOptions={yearOpts}
            onViewModeChange={handlePeriodModeChange}
            onMonthChange={handleMonthChange}
            onYearChange={handleYearChange}
            onQuarterChange={handleQuarterChange}
          />
        )}
        leading={(
          <div data-testid={`${TEST_ID}-field-warehouse`}>
            <Select
              label="Kho"
              value={warehouseId}
              onChange={e => setWarehouseId(e.target.value)}
              options={[
                { value: '', label: 'Tất cả kho' },
                ...warehouses.map(w => ({ value: String(w.id), label: w.name })),
              ]}
              size="small"
            />
          </div>
        )}
      />
    ),
    [fromDate, toDate, warehouseId, warehouses, handleLoad, loading, viewMode, month, year, quarter, yearOpts],
  );

  return (
    <AnalyticsReportShell
      testId={TEST_ID}
      pageId={PAGE_ID}
      title="Nhập xuất tồn"
      titleIconClass="fas fa-boxes"
      loading={loading}
      hasData={rows.length > 0}
      filters={listFilters}
      onLoad={handleLoad}
      exportPath="/wms/reports/nxt/export-excel"
      exportParams={{ fromDate, toDate, warehouseId: warehouseId || undefined }}
      exportFilename={`NXT-${fromDate}.xlsx`}
    >
      <ReportTableWrap testId={`${TEST_ID}-grid`}>
        <thead>
          <tr>
            <th className={reportStyles.colStt}>STT</th>
            <th>Mã</th>
            <th>Tên</th>
            <th>Kho</th>
            <th className={reportStyles.colRight}>Tồn đầu</th>
            <th className={reportStyles.colRight}>Nhập</th>
            <th className={reportStyles.colRight}>Xuất</th>
            <th className={reportStyles.colRight}>Tồn cuối</th>
            <th className={reportStyles.colRight}>Giá trị</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((r, i) => (
            <tr key={`${r.warehouseId ?? r.warehouseName}-${r.materialCode}-${i}`}>
              <td className={reportStyles.colStt}>{i + 1}</td>
              <td>{r.materialCode}</td>
              <td>{r.materialName}</td>
              <td>{r.warehouseName}</td>
              <td className={reportStyles.colRight}>{formatNumber(r.openingQuantity)}</td>
              <td className={reportStyles.colRight}>{formatNumber(r.receivedQuantity)}</td>
              <td className={reportStyles.colRight}>{formatNumber(r.issuedQuantity)}</td>
              <td className={reportStyles.colRight}>{formatNumber(r.closingQuantity)}</td>
              <td className={reportStyles.colRight}>{formatVnd(r.closingAmount)}</td>
            </tr>
          ))}
          {rows.length > 0 && (
            <tr className={reportStyles.rowTotal}>
              <td className={reportStyles.colStt} />
              <td colSpan={3}>Tổng cộng</td>
              <td className={reportStyles.colRight} />
              <td className={reportStyles.colRight} />
              <td className={reportStyles.colRight} />
              <td className={reportStyles.colRight} />
              <td className={reportStyles.colRight}>{formatVnd(totalClosing)}</td>
            </tr>
          )}
        </tbody>
      </ReportTableWrap>
    </AnalyticsReportShell>
  );
};

export default BaoCaoNxtPage;
